"""I6: the generators hold no Morph-specific code, and removing it changes no generated byte.

The Morph rollup library (window and challenge helpers, the ghost-tag and header projections, the
aggregate stand-in), the Go slice library and the explorer's search hints move out of holon/ into
target inputs under spec/. The pins below were computed at the I6 prereg from the committed tree:
regenerating with the generic generators must reproduce them exactly. A toy, non-Morph machine
runs end to end through the same generators.
"""
import hashlib
import json
import re
import shutil
import unittest
from pathlib import Path

from tests_m2._m2 import ROOT, copy_repo, load_json, run_holon, write_json

GEN_PIN = "6f37a5ff7efa27bb6a37b5ca4338fe0367168c7d3c4f0c3586c4825f20363f02"
BINDINGS_PIN = "21abdac393b68ae6be544dc340c5de3273f2ec3915f1ab96f1090cf2fb8eb857"
RECORDS_PIN = "38c704e6dc1170bfcc80cbbff339c40a7743c458f59a2e42e29a4487ff9594cf"

# Morph identifiers: none may appear in the generic generator modules after I6.
MORPH = re.compile(r"\b(win_at|win_last|nth_ch|set_ch|bump_f|any_open|clear_chs|zero_csr|set_last_csr|tags_exact|"
                   r"hdr_of|empty_entry|empty_ch|HEntry|HCh|HBD|AGG_BASE|blob_count|commitBatch|commitState|"
                   r"commitBatchWithProof|revertBatch|challengeState|proveState|finalizeBatch|setPause|sendMessage|"
                   r"batchdata|Rollup|Morph|morph)\b")
GENERIC = ["holon/gen/machine.py", "holon/gen/mlaws.py", "holon/gen/mproofs.py", "holon/gen/model.py",
           "holon/gen/laws.py", "holon/gen/proofs.py", "holon/js/explore.mjs", "holon/js/policy.mjs",
           "holon/mcanary.py", "holon/model_eval.py", "holon/mpipeline.py"]
ALLOWLIST: dict[str, list[str]] = {}

TOY = ROOT / "tests_m2" / "fixtures" / "toy_queue"


def tree_sha(root: Path, dirs: list[str], norm=None) -> str:
    h = hashlib.sha256()
    for d in dirs:
        for f in sorted((root / d).rglob("*")):
            if f.is_file() and "__pycache__" not in f.parts and "lean" not in f.relative_to(root / d).parts[:1]:
                # gen/<m>/lean/ is I9's second-kernel output, new by design (not a change to the Bend tree)
                b = f.read_bytes()
                if norm:
                    b = norm(f, b)
                rel = f.relative_to(root).as_posix()
                h.update(rel.encode() + b"\0" + hashlib.sha256(b).hexdigest().encode() + b"\n")
    return h.hexdigest()


def norm_record(f: Path, b: bytes) -> bytes:
    """Records compare modulo timing (`seconds`) and the generator hash, which changes by design
    when the generators change."""
    if not (f.name.startswith("L_") and f.suffix == ".json"):
        return b

    def s(x):
        if isinstance(x, dict):
            return {k: s(v) for k, v in x.items() if k not in ("seconds", "generator_sha256")}
        if isinstance(x, list):
            return [s(v) for v in x]
        return x
    rec = json.loads(b)
    # I16 fills refinement_refs: a filled list is compared as its pinned pre-I16 value "pending:I16";
    # every other field is compared as before
    if isinstance(rec.get("refinement_refs"), list):
        rec["refinement_refs"] = "pending:I16"
    # I9 adds a checked lean4 kernel entry, which earns I2; without it the record is exactly the pinned one
    lean = [k for k in rec.get("kernels", []) if k.get("name") == "lean4"]
    if lean:
        rec["kernels"] = [k for k in rec["kernels"] if k.get("name") != "lean4"]
        if rec.get("independence_class") == "I2" and lean[0].get("result") == "checked":
            rec["independence_class"] = "I1-shared"
    # I14 adds the v2 evidence fields; without them the record is exactly the pinned one
    for k in ("evidence_levels", "evidence_triage", "evidence_override"):
        rec.pop(k, None)
    return json.dumps(s(rec), sort_keys=True).encode()


def records_sha(root: Path) -> str:
    h = hashlib.sha256()
    for m in ("M0", "M1"):
        for f in sorted((root / "results" / m).glob("L_*.json")) + [root / "results" / m / "summary.json",
                                                                       root / "results" / m / "deps.json"]:
            b = norm_record(f, f.read_bytes())
            h.update(f.relative_to(root).as_posix().encode() + b"\0" + hashlib.sha256(b).hexdigest().encode() + b"\n")
    return h.hexdigest()


class TestByteIdentity(unittest.TestCase):
    def test_generated_files_unchanged(self):
        """I6-P1."""
        self.assertEqual(tree_sha(ROOT, ["gen/M0", "gen/M1"]), GEN_PIN)

    def test_bindings_unchanged(self):
        """I6-P1."""
        self.assertEqual(tree_sha(ROOT, ["spec/bindings"]), BINDINGS_PIN)

    def test_records_unchanged_modulo_seconds_and_generator_hash(self):
        """I6-P2."""
        self.assertEqual(records_sha(ROOT), RECORDS_PIN)


class TestNoMorphInGenerators(unittest.TestCase):
    def test_generic_modules_hold_no_morph_identifier(self):
        """I6-P3."""
        for rel in GENERIC:
            p = ROOT / rel
            if not p.exists():
                continue
            with self.subTest(file=rel):
                found = sorted(set(MORPH.findall(p.read_text(encoding="utf-8"))))
                self.assertEqual(found, ALLOWLIST.get(rel, []))
        self.assertFalse((ROOT / "holon" / "js" / "policy_lib.mjs").exists(), "the Morph search hints left holon/")

    def test_target_libraries_live_under_spec(self):
        for rel in ("spec/M1/lib/morph_rollup.lib.json", "spec/lib/go_slices.lib.json", "spec/M1/policy_hints.mjs"):
            with self.subTest(file=rel):
                self.assertTrue((ROOT / rel).exists())


class TestToyMachine(unittest.TestCase):
    """I6-P4: a non-Morph machine through the same generators, pipeline and kernel."""

    def test_planted_true_law_proved_and_false_law_refuted(self):
        repo = copy_repo()
        try:
            facts_rel = "tests_m2/fixtures/toy_queue/toy_queue.facts.json"
            sha = hashlib.sha256((repo / facts_rel).read_bytes()).hexdigest()
            d = repo / "laws" / "T0"
            d.mkdir(parents=True)
            stmts = {}
            for name in ("L_toy_reach", "L_toy_small"):
                law = load_json(TOY / f"{name}.json")
                law["facts_sha256"] = sha
                write_json(d / f"{name}.json", law)
                stmts[name] = None
            write_json(d / "REGISTRY.json", {"milestone": "T0", "facts": facts_rel, "facts_sha256": sha,
                                             "facts_files": {facts_rel: sha}, "statements": stmts})
            out, gen = repo / "t0_results", repo / "t0_gen"
            p = run_holon(["run", "--milestone", "T0", "--no-registry", "--out", str(out), "--gen-dir", str(gen)],
                          cwd=repo)
            self.assertEqual(p.returncode, 0, p.stdout[-2000:] + p.stderr[-2000:])
            reach = load_json(out / "L_toy_reach.json")
            small = load_json(out / "L_toy_small.json")
            self.assertEqual(reach["status"], "PROVED", reach.get("attempts"))
            self.assertEqual(small["status"], "REFUTED", small.get("attempts"))
            pushes = [a for a in small["witness"]["p"] if a["op"] == "push"]
            self.assertGreaterEqual(len(pushes), 3, small["witness"])
            model = next((gen / "model").glob("*.bend")).read_text()
            self.assertIsNone(MORPH.search(model), "a toy model must not carry Morph library code")
        finally:
            shutil.rmtree(repo.parent, ignore_errors=True)


if __name__ == "__main__":
    unittest.main()
